import csv
import json
from datetime import date

AUDIT_DATE = date(2026, 3, 31)

# --- Load licences ---
licences = {}
with open('/app/input/licensed_property_register.csv', newline='') as f:
    for row in csv.DictReader(f):
        licences[row['license_id']] = {
            'property_name': row['property_name'],
            'license_type': row['license_type'],
            'covers_distribution': row['covers_distribution'],
            'valid_until': date.fromisoformat(row['valid_until']),
        }

# --- Load accounts ---
accounts = {}
with open('/app/input/client_accounts.csv', newline='') as f:
    for row in csv.DictReader(f):
        covers = row['master_agreement_covers']
        accounts[row['account_id']] = {
            'account_name': row['account_name'],
            'account_type': row['account_type'],
            'covers': set() if covers == 'none' else set(covers.split(';')),
            'status': row['agreement_status'],
        }

# --- Load requests ---
requests = []
with open('/app/input/composite_request_log.csv', newline='') as f:
    for row in csv.DictReader(f):
        row['subject_is_minor'] = row['subject_is_minor'] == 'True'
        row['alteration_disclosure_on_file'] = row['alteration_disclosure_on_file'] == 'True'
        requests.append(row)

FINDING_ORDER = [
    'UNLICENSED_CHARACTER_USE',
    'THIRD_PARTY_BACKGROUND_UNLICENSED',
    'MISSING_MINOR_CONSENT',
    'COMMERCIAL_DISTRIBUTION_FLAG',
    'ALTERATION_DISCLOSURE_MISSING',
]

def licence_covers(license_id, need_type, distribution):
    """§2: a licence covers a request for the given use type and distribution."""
    if license_id == 'none' or license_id == '':
        return (False, 'no licence id on row')
    lic = licences.get(license_id)
    if lic is None:
        return (False, 'licence id not in register')
    if lic['license_type'] != need_type:
        return (False, f"license_type {lic['license_type']} != {need_type}")
    covers = lic['covers_distribution']
    dists = set(covers.split(';'))
    if distribution not in dists and covers != 'all':
        return (False, f"distribution {distribution} not in covers {covers}")
    if lic['valid_until'] < AUDIT_DATE:
        return (False, f"expired {lic['valid_until'].isoformat()}")
    return (True, f"covered by {license_id}")

def audit_request(r):
    findings = []
    reasons = {}
    dist = r['intended_distribution']

    # §3 Licensed-character use
    if r['character_property'] != 'none':
        cleared = False
        cleared_by = None
        ok, why = licence_covers(r['character_license_id'], 'character', dist)
        if ok:
            cleared = True
            cleared_by = f"licence {r['character_license_id']}"
        # personal-use allowance
        if dist == 'personal_only':
            cleared = True
            cleared_by = 'personal-use allowance'
        if not cleared:
            findings.append('UNLICENSED_CHARACTER_USE')
            reasons['UNLICENSED_CHARACTER_USE'] = (
                f"character {r['character_property']}; "
                f"licence {r['character_license_id']} does not cover "
                f"({why}); not personal_only (dist={dist})"
            )
        else:
            reasons['_char_cleared_by'] = cleared_by

    # §4 Third-party backgrounds
    bs = r['background_source']
    if bs == 'customer_original':
        pass
    elif bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
        reasons['THIRD_PARTY_BACKGROUND_UNLICENSED'] = (
            "background_source third_party_unlicensed (own record; "
            f"licence id {r['background_license_id']} not looked up per §4)"
        )
    elif bs == 'third_party_licensed':
        ok, why = licence_covers(r['background_license_id'], 'background', dist)
        if not ok:
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
            reasons['THIRD_PARTY_BACKGROUND_UNLICENSED'] = (
                f"third_party_licensed; licence {r['background_license_id']} "
                f"does not cover ({why})"
            )
        else:
            reasons['_bg_cleared_by'] = f"licence {r['background_license_id']}"

    # §5 Minor consent
    if r['subject_is_minor']:
        ctype = r['minor_consent_type']
        problems = []
        if ctype == 'none' or ctype == '':
            problems.append('not present')
        else:
            try:
                v = date.fromisoformat(r['minor_consent_valid_until'])
            except Exception:
                v = None
            if v is None or v < AUDIT_DATE:
                problems.append(f"not current (valid_until {r['minor_consent_valid_until']})")
            else:
                # wide enough?
                if ctype == 'basic' and dist not in ('personal_only', 'client_internal'):
                    problems.append(f"basic consent too narrow for {dist}")
                # publicity covers every distribution
        if problems:
            findings.append('MISSING_MINOR_CONSENT')
            reasons['MISSING_MINOR_CONSENT'] = "; ".join(problems)

    # §6 Commercial distribution routing
    if dist in ('social_public', 'print_for_sale'):
        acc = accounts[r['account_id']]
        cleared = acc['status'] == 'active' and dist in acc['covers']
        if not cleared:
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')
            if acc['status'] != 'active':
                reasons['COMMERCIAL_DISTRIBUTION_FLAG'] = (
                    f"account {r['account_id']} agreement {acc['status']} "
                    f"(lapsed covers nothing)"
                )
            else:
                reasons['COMMERCIAL_DISTRIBUTION_FLAG'] = (
                    f"account {r['account_id']} active but covers "
                    f"{';'.join(sorted(acc['covers'])) or 'none'}; "
                    f"{dist} not covered"
                )

    # §7 Alteration disclosure
    if (r['alteration_level'] == 'substantive' and
            dist in ('social_public', 'print_for_sale')):
        if not r['alteration_disclosure_on_file']:
            findings.append('ALTERATION_DISCLOSURE_MISSING')
            reasons['ALTERATION_DISCLOSURE_MISSING'] = (
                "substantive alteration to public/paid distribution; "
                "disclosure not on file"
            )

    # order findings
    ordered = [f for f in FINDING_ORDER if f in findings]
    finding_str = '|'.join(ordered) if ordered else 'none'
    return ordered, finding_str, reasons

# --- Audit all requests ---
audit = {}
for r in requests:
    ordered, finding_str, reasons = audit_request(r)
    audit[r['request_id']] = {
        'findings': ordered,
        'finding_str': finding_str,
        'reasons': reasons,
        'account_id': r['account_id'],
        'row': r,
    }

# --- Write composite_request_audit.csv ---
with open('/app/composite_request_audit.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['request_id', 'finding'])
    for r in requests:
        w.writerow([r['request_id'], audit[r['request_id']]['finding_str']])

# --- Account summary + escalation ---
acct_reqs = {a: [] for a in accounts}
for r in requests:
    acct_reqs[r['account_id']].append(r['request_id'])

account_summary = {}
with open('/app/account_summary.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['account_id', 'account_type', 'request_count',
                'flagged_requests', 'escalation'])
    for aid in sorted(accounts):
        rids = acct_reqs[aid]
        flagged = [rid for rid in rids if audit[rid]['findings']]
        n_flagged = len(flagged)
        max_findings = max((len(audit[rid]['findings']) for rid in rids), default=0)
        escalate = (n_flagged >= 2) or (max_findings >= 3)
        esc_str = 'ESCALATION_REQUIRED' if escalate else 'none'
        account_summary[aid] = {
            'account_type': accounts[aid]['account_type'],
            'request_count': len(rids),
            'flagged_requests': n_flagged,
            'escalation': esc_str,
            'flagged_list': flagged,
            'max_findings': max_findings,
        }
        w.writerow([aid, accounts[aid]['account_type'], len(rids),
                    n_flagged, esc_str])

# --- results.json ---
flagged_count = sum(1 for r in requests if audit[r['request_id']]['findings'])
finding_total = sum(len(audit[r['request_id']]['findings']) for r in requests)
def count_finding(code):
    return sum(1 for r in requests if code in audit[r['request_id']]['findings'])
escalated = sum(1 for a in accounts if account_summary[a]['escalation'] == 'ESCALATION_REQUIRED')

results = {
    'request_count': len(requests),
    'account_count': len(accounts),
    'flagged_count': flagged_count,
    'compliant_count': len(requests) - flagged_count,
    'finding_total': finding_total,
    'character_count': count_finding('UNLICENSED_CHARACTER_USE'),
    'background_count': count_finding('THIRD_PARTY_BACKGROUND_UNLICENSED'),
    'consent_count': count_finding('MISSING_MINOR_CONSENT'),
    'commercial_count': count_finding('COMMERCIAL_DISTRIBUTION_FLAG'),
    'disclosure_count': count_finding('ALTERATION_DISCLOSURE_MISSING'),
    'escalated_accounts': escalated,
}
with open('/app/results.json', 'w') as f:
    json.dump(results, f, indent=2)

# --- Print detail for memo writing ---
print("=== REQUEST AUDIT ===")
for r in requests:
    a = audit[r['request_id']]
    print(f"{r['request_id']} ({r['account_id']}) [{r['character_property']}/"
          f"{r['background_source']}/{r['intended_distribution']}]: {a['finding_str']}")
    for k, v in a['reasons'].items():
        print(f"    {k}: {v}")

print("\n=== ACCOUNT SUMMARY ===")
for aid in sorted(accounts):
    s = account_summary[aid]
    print(f"{aid} {s['account_type']} reqs={s['request_count']} "
          f"flagged={s['flagged_requests']} ({s['flagged_list']}) "
          f"max={s['max_findings']} esc={s['escalation']}")

print("\n=== RESULTS ===")
print(json.dumps(results, indent=2))

# personal-use allowance cleared character requests
print("\n=== PERSONAL-USE ALLOWANCE CLEARS (character) ===")
for r in requests:
    a = audit[r['request_id']]
    if (r['character_property'] != 'none' and
            'UNLICENSED_CHARACTER_USE' not in a['findings'] and
            a['reasons'].get('_char_cleared_by') == 'personal-use allowance'):
        print(r['request_id'], r['character_property'], r['character_license_id'])

# lapsed accounts
print("\n=== LAPSED ACCOUNTS ===")
for aid in sorted(accounts):
    if accounts[aid]['status'] == 'lapsed':
        print(aid, accounts[aid]['account_name'],
              "covers recorded:", accounts[aid]['covers'])

# escalated reasons
print("\n=== ESCALATION REASONS ===")
for aid in sorted(accounts):
    s = account_summary[aid]
    if s['escalation'] == 'ESCALATION_REQUIRED':
        print(f"{aid}: flagged={s['flagged_requests']} "
              f"({s['flagged_list']}) max_findings={s['max_findings']}")
